import Foundation
import XCTest
@testable import HyleTokens
#if canImport(UIKit)
import UIKit
#elseif canImport(AppKit)
import AppKit
#endif

final class HyleTokensTests: XCTestCase {
    func testTokenCounts() {
        XCTAssertEqual(HyleTokens.Color.all.count, 54)
        XCTAssertEqual(HyleTokens.Size.all.count, 31)
    }

    func testColourComponentsAreUnitRange() {
        for (name, c) in HyleTokens.Color.all {
            for v in [c.red, c.green, c.blue, c.alpha] {
                XCTAssertTrue((0.0...1.0).contains(v), "\(name) out of range")
            }
        }
    }

    func testArgbDecoding() {
        let c = HyleRGBA(argb: 0xFF8E7BFF)
        XCTAssertEqual(c, HyleTokens.Color.colorPaletteAccentViolet)
        XCTAssertEqual(c.red, Double(0x8E) / 255, accuracy: 1e-9)
        XCTAssertEqual(c.alpha, 1.0, accuracy: 1e-9)
    }

    func testDurationsArePositiveIntegers() {
        XCTAssertGreaterThan(HyleTokens.Milliseconds.durationInstant, 0)
        XCTAssertGreaterThan(HyleTokens.Milliseconds.durationCalm, 0)
        XCTAssertGreaterThan(HyleTokens.Milliseconds.durationPane, 0)
    }

#if canImport(UIKit)
    /// iPhone and iPad share one set of values: no token is idiom-specific, so a
    /// colour resolved under either idiom equals the plain RGBA.
    func testPhoneAndPadResolveIdentically() {
        let phone = UITraitCollection(userInterfaceIdiom: .phone)
        let pad = UITraitCollection(userInterfaceIdiom: .pad)
        for (name, c) in HyleTokens.Color.all {
            var a: (CGFloat, CGFloat, CGFloat, CGFloat) = (0, 0, 0, 0)
            var b: (CGFloat, CGFloat, CGFloat, CGFloat) = (0, 0, 0, 0)
            c.uiColor.resolvedColor(with: phone).getRed(&a.0, green: &a.1, blue: &a.2, alpha: &a.3)
            c.uiColor.resolvedColor(with: pad).getRed(&b.0, green: &b.1, blue: &b.2, alpha: &b.3)
            XCTAssertEqual(a.0, b.0, accuracy: 1e-6, name)
            XCTAssertEqual(a.1, b.1, accuracy: 1e-6, name)
            XCTAssertEqual(a.2, b.2, accuracy: 1e-6, name)
            XCTAssertEqual(a.3, b.3, accuracy: 1e-6, name)
            XCTAssertEqual(Double(a.0), c.red, accuracy: 1e-3, name)
        }
    }
#elseif canImport(AppKit)
    func testAppKitColourMatchesPlainRGBA() {
        for (name, c) in HyleTokens.Color.all {
            let n = c.nsColor.usingColorSpace(.sRGB)
            XCTAssertNotNil(n, name)
            XCTAssertEqual(Double(n?.redComponent ?? -1), c.red, accuracy: 1e-3, name)
            XCTAssertEqual(Double(n?.alphaComponent ?? -1), c.alpha, accuracy: 1e-3, name)
        }
    }
#endif
}
